from slack_bolt import App
from slack_bolt.adapter.socket_mode import SocketModeHandler

# Bot Token과 App-Level Token 필요
app = App(token="xoxb-your-bot-token")

@app.message("hello")
def handle_hello(message, say):
    say(f"안녕하세요 <@{message['user']}>!")

@app.action("approve_button")  # 버튼 클릭 이벤트
def handle_approve(ack, body, say):
    ack()  # 3초 이내 응답
    say("승인되었습니다")

if __name__ == "__main__":
    # WebSocket 연결 시작, 공개 URL 불필요
    handler = SocketModeHandler(app, "xapp-your-app-token")
    handler.start()
